import{z as l,x as n,o as t,c as d,q as B,j as s,D as A,d as a,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"云安全模型","description":"","frontmatter":{"title":"云安全模型","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ss-cloud-model.md","filePath":"cs/ss-cloud-model.md","lastUpdated":1791063341000}'),c={name:"cs/ss-cloud-model.md"};function D(u,E,p,C,S,h){const r=n("Mermaid");return t(),d("div",null,[E[2]||(E[2]=B('<h1 id="云安全模型" tabindex="-1">云安全模型 <a class="header-anchor" href="#云安全模型" aria-label="Permalink to &quot;云安全模型&quot;">​</a></h1><div class="epigraph"><p>云的第一份礼物是「基座有人替你守」，第二份是「守门的钥匙换成了你写的策略」；事故的重心随之从攻破转为配错。</p><footer>—— 据 NIST SP 800-145；2019 年 Capital One 事件法庭材料与 AWS 文档整理</footer></div><p><a href="/cs/ss-mobile">上一课</a>收在单机多格子的平台标本；云把问题升一维——格子换成多租户共享的机房，格子之下不再是你的内核。主干已有<a href="/cs/virt-security-boundary">虚拟化安全边界</a>、<a href="/cs/container-escape">容器逃逸</a>、<a href="/cs/confidential-computing">机密计算</a>与<a href="/cs/zero-trust-architecture">零信任架构</a>；本课写云自己的安全模型：责任怎么分、边界画在哪、身份为什么取代位置成为边界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IaaS、PaaS、SaaS 三种服务模型各画一条责任分界（NIST SP 800-145 的口径）：服务方守物理、虚拟化与控制面的地基，你守身份、配置与数据。事故的重心随之移动：云上的大头不是攻破虚拟化层——那要穿过<a href="/cs/virt-security-boundary">虚拟化边界</a>量过 TCB 的一整层——而是误配置与凭据：公开的存储桶、过宽的 IAM 策略、被 SSRF 偷走的角色凭据。缺口是：把「配错」当一类可分类、可缓解的漏洞来写，而不是当运维事故道歉了事。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="模型件五件" tabindex="-1">模型件五件 <a class="header-anchor" href="#模型件五件" aria-label="Permalink to &quot;模型件五件&quot;">​</a></h3><p>IAM：策略语言几乎能表达任何规则，表达力就是新的攻击面，最小权限在云端必须落成「每条策略可审计、可差异比对」。元数据服务：实例自举用的本地 HTTP 端点，一次 SSRF 直达实例角色的临时凭据——IMDSv2 用会话 token 与默认拒绝抬高门槛。KMS 与加密：密钥归属是责任分割的钉子，谁持钥谁担责。审计日志：控制面每个动作留痕，是检测面的地基。机密计算：把「服务方也在 TCB 里」的那一段移走，用<a href="/cs/confidential-computing">远程证明</a>而不是合同背书。</p><p><span class="marginnote">Capital One 2019：WAF 误配让一次 SSRF 打进 IMDSv1，读到实例角色的临时凭据，约 1.06 亿申请人的记录外泄；AWS 同年年底推 IMDSv2，凭据改为 token 化请求获取。据法庭文件与 AWS 文档整理。</span></p><p><span class="marginnote">术语翻译：IMDS（实例元数据服务）就是云给每台虚拟机留的一个本地问询台——机器开机时问「我是谁、我能扮演什么角色」，答案里就带临时凭据；因为它只对本机开放，应用一旦被 SSRF，问询台就被外人顶替使用了。</span></p>',10)),(t(),s(i,null,{default:A(()=>[o(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROV%5B%22%E6%9C%8D%E5%8A%A1%E6%96%B9%EF%BC%9A%E7%89%A9%E7%90%86%20%2F%20%E8%99%9A%E6%8B%9F%E5%8C%96%20%2F%20%E6%8E%A7%E5%88%B6%E9%9D%A2%E5%9C%B0%E5%9F%BA%22%5D%20--%3E%20YOU%5B%22%E4%BD%A0%EF%BC%9A%E8%BA%AB%E4%BB%BD%20%2F%20%E9%85%8D%E7%BD%AE%20%2F%20%E6%95%B0%E6%8D%AE%22%5D%0A%20%20IAM%5B%22IAM%20%E7%AD%96%E7%95%A5%22%5D%20--%3E%20YOU%0A%20%20MIS%5B%22%E8%AF%AF%E9%85%8D%EF%BC%9A%E8%BF%87%E5%AE%BD%E7%AD%96%E7%95%A5%20%2F%20%E5%85%AC%E5%BC%80%E6%A1%B6%22%5D%20--%3E%20LEAK%5B%22%E6%9A%B4%E9%9C%B2%E9%9D%A2%22%5D%0A%20%20SSRF%5B%22%E5%BA%94%E7%94%A8%20SSRF%22%5D%20--%3E%20IMDS%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E6%9C%8D%E5%8A%A1%22%5D%0A%20%20IMDS%20--%3E%20CREDS%5B%22%E5%AE%9E%E4%BE%8B%E8%A7%92%E8%89%B2%E4%B8%B4%E6%97%B6%E5%87%AD%E6%8D%AE%22%5D%0A%20%20CREDS%20--%3E%20LEAK%0A%20%20AUD%5B%22%E5%AE%A1%E8%AE%A1%E6%97%A5%E5%BF%97%E4%B8%8E%E6%A3%80%E6%B5%8B%E9%9D%A2%22%5D%20--%3E%20LEAK%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("误配置为何成为云上的主要根因：控制面的表达力乘以默认值乘以环境漂移。它的结构正是"),e("a",{href:"/cs/ss-kernel-vuln-classes"},"内核漏洞类别"),a("逻辑类在配置层的重现——分类表可以整体复用：根因轴换成「策略如何写错」，原语轴换成「拿到什么凭据」：过宽的 IAM 等价于缺一次权限检查，SSRF 取 IMDS 等价于信任混淆，公开桶等价于把内部客体挂上全局可读。缓解也按格对号：策略差异审计对逻辑类，token 化取凭据对信任混淆，密钥归属对原语升级。"),e("a",{href:"/cs/zero-trust-architecture"},"零信任"),a("补上边界的另一半：位置不再是身份，每请求重新评估——云把网络边界溶解之后，身份是剩下的那道墙。")],-1)),(t(),s(i,null,{default:A(()=>[o(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20K%5B%22%E5%86%85%E6%A0%B8%E7%B1%BB%E5%88%AB%3A%20%E5%86%85%E5%AD%98%E5%B1%82%22%5D%0A%20%20%20%20K1%5B%22%E9%80%BB%E8%BE%91%E7%B1%BB%3A%20%E7%BC%BA%E6%9D%83%E9%99%90%E6%A3%80%E6%9F%A5%22%5D%0A%20%20%20%20K2%5B%22%E4%BF%A1%E4%BB%BB%E6%B7%B7%E6%B7%86%3A%20%E5%86%85%E6%A0%B8%E4%BF%A1%E4%BA%86%E9%94%99%E7%9A%84%E7%8E%AF%E7%BA%A7%22%5D%0A%20%20%20%20K3%5B%22%E6%9D%83%E9%99%90%E5%8D%87%E7%BA%A7%3A%20%E5%86%85%E9%83%A8%E5%AE%A2%E4%BD%93%E8%A2%AB%E5%85%A8%E5%B1%80%E5%8F%AF%E8%AF%BB%22%5D%0A%20%20end%0A%20%20subgraph%20C%5B%22%E4%BA%91%E7%B1%BB%E5%88%AB%3A%20%E9%85%8D%E7%BD%AE%E5%B1%82%22%5D%0A%20%20%20%20C1%5B%22%E8%BF%87%E5%AE%BD%20IAM%20%E7%AD%96%E7%95%A5%22%5D%0A%20%20%20%20C2%5B%22SSRF%20%E7%9B%B4%E5%8F%96%20IMDS%20%E5%87%AD%E6%8D%AE%22%5D%0A%20%20%20%20C3%5B%22%E5%AD%98%E5%82%A8%E6%A1%B6%E5%85%AC%E5%BC%80%E5%8F%AF%E5%86%99%22%5D%0A%20%20end%0A%20%20K1%20%3C--%3E%7C%22%E5%90%8C%E6%9E%84%E6%98%A0%E5%B0%84%22%7C%20C1%0A%20%20K2%20%3C--%3E%7C%22%E5%90%8C%E6%9E%84%E6%98%A0%E5%B0%84%22%7C%20C2%0A%20%20K3%20%3C--%3E%7C%22%E5%90%8C%E6%9E%84%E6%98%A0%E5%B0%84%22%7C%20C3%0A%20%20C1%20--%3E%20M1%5B%22%E7%BC%93%E8%A7%A3%3A%20%E7%AD%96%E7%95%A5%E5%B7%AE%E5%BC%82%E5%AE%A1%E8%AE%A1%22%5D%0A%20%20C2%20--%3E%20M2%5B%22%E7%BC%93%E8%A7%A3%3A%20IMDSv2%20token%20%E5%8C%96%22%5D%0A%20%20C3%20--%3E%20M3%5B%22%E7%BC%93%E8%A7%A3%3A%20%E5%AF%86%E9%92%A5%E5%BD%92%E5%B1%9E%E9%92%89%E8%B4%A3%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">数字实例：最小权限落到实处就是这条策略从 <code>&quot;Resource&quot;: &quot;*&quot;</code> 改成 <code>&quot;Resource&quot;: &quot;arn:aws:s3:::report-bucket/*&quot;</code>——星号意味着这份凭据被偷走时全账号 500 个桶全丢；钉死到桶名后，失窃半径只剩一个目录。</span></p><p><span class="marginnote">直觉类比：责任分割像租公寓——楼道保安与消防是房东的事（物理与虚拟化层），你锁不锁房门、把钥匙借给谁是你的事（身份、配置与数据）；丢了东西先看分界线在哪一侧，再谈谁担责。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>hypervisor 与容器隔离的机制专课已讲，本课不重讲逃逸；合规框架（SOC 2、等保的条文清单）是流程不是机制，点到为止；具体厂商的产品名只作实例不作教学对象。可观测性如何落地检测面，属于可观测性课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>责任分界随服务模型移动：服务方守地基，你守身份、配置与数据。</li><li>云上大头是误配置与凭据，不是攻破虚拟化层；模型件五件各管一段。</li><li>误配是内核类别表逻辑类的配置层重现：根因轴换「策略写错」，原语轴换「拿到凭据」。</li><li>IMDSv2 的 token 化是信任混淆的工程解；零信任把身份立为剩下的边界。</li><li>出处：NIST SP 800-145；Capital One 2019 法庭材料；AWS 文档；对照 <a href="/cs/virt-security-boundary">virt-security-boundary</a>、<a href="/cs/zero-trust-architecture">zero-trust-architecture</a>。</li></ul>',6))])}const F=l(c,[["render",D]]);export{f as __pageData,F as default};
